UPDATE "City" SET "published" = 1, "intro" = 'MS Mahj, led by instructor Linda McKnight, runs American Mah Jongg in Olive Branch and across the Mississippi side of the Memphis area, from lessons at Farrell''s Fantastic Fibers in Olive Branch to leagues, tournaments and socials at The Game Table in Horn Lake and venues in Southaven and Tunica. Tickets are sold online through its booking page. If you have never played, start with the Mah Jongg Lessons in Olive Branch, then move on to the leagues and socials once you know the basics.' WHERE "slug" = 'olive-branch';
